import{_ as e,o as t,c as o,a2 as s}from"./chunks/framework.C0KMm31j.js";const l="/Nav2ArticlesSite/article-assets/2026-07-27/graceful_core_01_overview.png",n="/Nav2ArticlesSite/article-assets/2026-07-27/graceful_core_02_path_target.png",i="/Nav2ArticlesSite/article-assets/2026-07-27/graceful_core_03_ego_polar.png",c="/Nav2ArticlesSite/article-assets/2026-07-27/graceful_core_04_curvature_law.png",r="/Nav2ArticlesSite/article-assets/2026-07-27/graceful_core_05_motion_modes.png",p="/Nav2ArticlesSite/article-assets/2026-07-27/graceful_core_06_collision_rollout.png",x=JSON.parse('{"title":"不采样、不打分，一条公式如何让机器人优雅转弯？拆解 Nav2 Graceful Controller 核心算法","description":"DWB 会采样速度并给轨迹打分，MPPI 会批量 rollout 并迭代优化。nav2gracefulcontroller 走的是另一条路：它从全局路径上取一个运动目标，把目标改写成机器人视角下的极坐标，再用一条基于 Lyapunov 思想的平滑控制律直接算出曲率、线速度和角速度。","frontmatter":{"title":"不采样、不打分，一条公式如何让机器人优雅转弯？拆解 Nav2 Graceful Controller 核心算法","description":"DWB 会采样速度并给轨迹打分，MPPI 会批量 rollout 并迭代优化。nav2gracefulcontroller 走的是另一条路：它从全局路径上取一个运动目标，把目标改写成机器人视角下的极坐标，再用一条基于 Lyapunov 思想的平滑控制律直接算出曲率、线速度和角速度。","date":"2026-07-27","topic":"Nav2 工程实践","section":"三 · 局部控制与速度生成","readingTime":15,"source":"2026-07-27/nav2_graceful_controller_core_algorithm.md","status":"published","cover":"/article-assets/2026-07-27/graceful_core_01_overview.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-graceful-controller-core-algorithm"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"不采样、不打分，一条公式如何让机器人优雅转弯？拆解 Nav2 Graceful Controller 核心算法"}],["meta",{"property":"og:description","content":"DWB 会采样速度并给轨迹打分，MPPI 会批量 rollout 并迭代优化。nav2gracefulcontroller 走的是另一条路：它从全局路径上取一个运动目标，把目标改写成机器人视角下的极坐标，再用一条基于 Lyapunov 思想的平滑控制律直接算出曲率、线速度和角速度。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-graceful-controller-core-algorithm"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-27/graceful_core_01_overview.png"}],["meta",{"property":"article:published_time","content":"2026-07-27"}],["meta",{"name":"twitter:title","content":"不采样、不打分，一条公式如何让机器人优雅转弯？拆解 Nav2 Graceful Controller 核心算法"}],["meta",{"name":"twitter:description","content":"DWB 会采样速度并给轨迹打分，MPPI 会批量 rollout 并迭代优化。nav2gracefulcontroller 走的是另一条路：它从全局路径上取一个运动目标，把目标改写成机器人视角下的极坐标，再用一条基于 Lyapunov 思想的平滑控制律直接算出曲率、线速度和角速度。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-27/graceful_core_01_overview.png"}]],"prev":{"text":"一条 Path，如何被 53 个函数炼成速度？逐函数拆解 Nav2 Controller Server","link":"/nav2/nav2-controller-source-walkthrough"},"next":{"text":"不选冠军，让 1000 种未来一起投票：Nav2 MPPI 如何炼出一条速度？","link":"/nav2/nav2-mppi-controller-core-algorithm"}},"headers":[],"relativePath":"nav2/nav2-graceful-controller-core-algorithm.md","filePath":"nav2/nav2-graceful-controller-core-algorithm.md","lastUpdated":null}'),d={name:"nav2/nav2-graceful-controller-core-algorithm.md"};function h(u,a,_,m,g,b){return t(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="不采样、不打分-一条公式如何让机器人优雅转弯-拆解-nav2-graceful-controller-核心算法" tabindex="-1">不采样、不打分，一条公式如何让机器人优雅转弯？拆解 Nav2 Graceful Controller 核心算法 <a class="header-anchor" href="#不采样、不打分-一条公式如何让机器人优雅转弯-拆解-nav2-graceful-controller-核心算法" aria-label="Permalink to &quot;不采样、不打分，一条公式如何让机器人优雅转弯？拆解 Nav2 Graceful Controller 核心算法&quot;">​</a></h1><p>DWB 会采样速度并给轨迹打分，MPPI 会批量 rollout 并迭代优化。<code>nav2_graceful_controller</code> 走的是另一条路：它从全局路径上取一个运动目标，把目标改写成机器人视角下的极坐标，再用一条基于 Lyapunov 思想的平滑控制律直接算出曲率、线速度和角速度。</p><p>它没有候选轨迹矩阵，也没有 Critic 权重表。每个控制周期只生成一条速度指令，再沿这条控制律向前积分出一条预测轨迹，用 Costmap 判断能否安全执行。</p><p>本文基于当前工程的 <code>nav2_graceful_controller 1.1.20</code>，只拆核心算法。Lifecycle 配置、Publisher 激活、Pluginlib 注册和可视化消息只说明接口边界，不展开成工程流程。</p><p><img src="'+l+`" alt="Graceful Controller 核心算法总数据流"></p><h2 id="一、核心边界-它究竟接收什么-又输出什么" tabindex="-1">一、核心边界：它究竟接收什么，又输出什么 <a class="header-anchor" href="#一、核心边界-它究竟接收什么-又输出什么" aria-label="Permalink to &quot;一、核心边界：它究竟接收什么，又输出什么&quot;">​</a></h2><h3 id="_1-1-输入不是一张局部轨迹候选表" tabindex="-1">1.1 输入不是一张局部轨迹候选表 <a class="header-anchor" href="#_1-1-输入不是一张局部轨迹候选表" aria-label="Permalink to &quot;1.1 输入不是一张局部轨迹候选表&quot;">​</a></h3><p><code>computeVelocityCommands()</code> 的主要输入是当前机器人位姿 <code>pose</code>、当前速度 <code>velocity</code> 和包外 <code>GoalChecker</code>。当前源码没有使用 <code>velocity</code> 参数，真正进入控制律的是当前位姿、已经保存的全局路径、动态参数以及目标检查器给出的距离容差。</p><p>全局路径由包外 Controller Server 通过 <code>setPlan()</code> 写入 <code>PathHandler::global_plan_</code>。后续每个控制周期都在这条路径上裁剪已走部分、截取局部片段并选择运动目标。</p><h3 id="_1-2-输出是一条-twiststamped" tabindex="-1">1.2 输出是一条 TwistStamped <a class="header-anchor" href="#_1-2-输出是一条-twiststamped" aria-label="Permalink to &quot;1.2 输出是一条 TwistStamped&quot;">​</a></h3><p>控制器最终输出：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>linear.x  = v</span></span>
<span class="line"><span>angular.z = ω</span></span></code></pre></div><p>差速机器人据此执行前进、倒车或原地旋转。<code>linear.y</code> 等其他分量保持零值。</p><h3 id="_1-3-算法同时输出一条验证轨迹" tabindex="-1">1.3 算法同时输出一条验证轨迹 <a class="header-anchor" href="#_1-3-算法同时输出一条验证轨迹" aria-label="Permalink to &quot;1.3 算法同时输出一条验证轨迹&quot;">​</a></h3><p>速度指令之外，控制器还用相同平滑控制律迭代调用 <code>calculateNextPose()</code>，生成 <code>local_plan</code>。这条 Path 主要承担碰撞预测和调试可视化，不参与候选轨迹比较。</p><p>因此它的核心不是“生成很多条再选一条”，而是“先算出唯一控制律，再验证这条控制律将把机器人带到哪里”。</p><h2 id="二、路径进入控制律前-先被裁剪到机器人附近" tabindex="-1">二、路径进入控制律前，先被裁剪到机器人附近 <a class="header-anchor" href="#二、路径进入控制律前-先被裁剪到机器人附近" aria-label="Permalink to &quot;二、路径进入控制律前，先被裁剪到机器人附近&quot;">​</a></h2><p><img src="`+n+'" alt="全局路径裁剪与运动目标选择"></p><h3 id="_2-1-transformglobalplan-先找到路径上的机器人附近点" tabindex="-1">2.1 transformGlobalPlan() 先找到路径上的机器人附近点 <a class="header-anchor" href="#_2-1-transformglobalplan-先找到路径上的机器人附近点" aria-label="Permalink to &quot;2.1 transformGlobalPlan() 先找到路径上的机器人附近点&quot;">​</a></h3><p><code>PathHandler::transformGlobalPlan()</code> 先通过包外 <code>nav_2d_utils::transformPose()</code>，把当前机器人位姿变换到全局路径坐标系。</p><p>源码不会在整条路径上无限搜索最近点。它用 <code>first_after_integrated_distance()</code> 沿路径累计距离，得到 <code>max_robot_pose_search_dist</code> 上界，再在这个范围内用 <code>min_by()</code> 找欧氏距离最小的路径点。</p><p>这一步避免路径在局部 Costmap 中回环时，控制器错误跳到更靠后的相交路段。</p><h3 id="_2-2-局部窗口只保留-costmap-能覆盖的路径" tabindex="-1">2.2 局部窗口只保留 Costmap 能覆盖的路径 <a class="header-anchor" href="#_2-2-局部窗口只保留-costmap-能覆盖的路径" aria-label="Permalink to &quot;2.2 局部窗口只保留 Costmap 能覆盖的路径&quot;">​</a></h3><p>从最近点开始，源码找到首个距机器人超过下式阈值的路径点：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dist_threshold = max(costmap_size_x, costmap_size_y) / 2</span></span></code></pre></div><p>最近点到该点之前的路径被逐点变换到机器人基坐标系。包外 TF 变换失败、原始路径为空或变换后路径为空，都会抛出 <code>nav2_core::PlannerException</code>。</p><p>已走过的原始路径段随后从 <code>global_plan_</code> 中删除。这个 path pruning 会改变包内保存的路径，使下个控制周期不再重复处理身后路段。</p><h3 id="_2-3-getmotiontarget-用径向距离选前视点" tabindex="-1">2.3 getMotionTarget() 用径向距离选前视点 <a class="header-anchor" href="#_2-3-getmotiontarget-用径向距离选前视点" aria-label="Permalink to &quot;2.3 getMotionTarget() 用径向距离选前视点&quot;">​</a></h3><p>变换后的路径已经位于机器人坐标系。<code>getMotionTarget()</code> 从头扫描，选择第一个满足下式的 Pose：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hypot(x, y) &gt;= motion_target_dist</span></span></code></pre></div><p>这里比较的是路径点到机器人原点的直线距离，不是沿路径累计距离。若所有点都不够远，就使用最后一个 Pose，也就是当前局部路径能够提供的最远目标。</p><h3 id="_2-4-距终点的判断使用路径累计距离" tabindex="-1">2.4 距终点的判断使用路径累计距离 <a class="header-anchor" href="#_2-4-距终点的判断使用路径累计距离" aria-label="Permalink to &quot;2.4 距终点的判断使用路径累计距离&quot;">​</a></h3><p>运动目标点用径向距离选择，但 <code>dist_to_goal</code> 使用 <code>calculate_path_length()</code> 对变换后路径逐段累计。</p><p>弯曲路径中，这两个距离并不相同：</p><ul><li>径向距离决定控制器现在追哪个点。</li><li>路径累计距离决定是否已经进入目标附近和最终旋转阶段。</li></ul><p>当 <code>final_rotation=true</code> 且剩余路径短于 <code>motion_target_dist</code>，源码会忽略目标 Pose 原本的朝向，改用路径最后一段的切线方向作为运动目标朝向。真正的目标朝向留给最后的原地旋转处理。</p><h2 id="三、三个自车极坐标-把目标位姿变成控制误差" tabindex="-1">三、三个自车极坐标，把目标位姿变成控制误差 <a class="header-anchor" href="#三、三个自车极坐标-把目标位姿变成控制误差" aria-label="Permalink to &quot;三、三个自车极坐标，把目标位姿变成控制误差&quot;">​</a></h2><p><img src="'+i+`" alt="运动目标到自车极坐标 r、phi、delta"></p><h3 id="_3-1-r-描述还要走多远" tabindex="-1">3.1 r 描述还要走多远 <a class="header-anchor" href="#_3-1-r-描述还要走多远" aria-label="Permalink to &quot;3.1 r 描述还要走多远&quot;">​</a></h3><p><code>EgocentricPolarCoordinates</code> 接收同一坐标系中的目标 Pose 和当前 Pose：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Δx = target.x - current.x</span></span>
<span class="line"><span>Δy = target.y - current.y</span></span>
<span class="line"><span>r  = sqrt(Δx² + Δy²)</span></span></code></pre></div><p>在实时速度计算中，当前 Pose 使用默认原点，因此 <code>r</code> 就是运动目标到机器人基坐标系原点的距离。</p><h3 id="_3-2-line-of-sight-建立机器人到目标的视线" tabindex="-1">3.2 line_of_sight 建立机器人到目标的视线 <a class="header-anchor" href="#_3-2-line-of-sight-建立机器人到目标的视线" aria-label="Permalink to &quot;3.2 line_of_sight 建立机器人到目标的视线&quot;">​</a></h3><p>正向运动时源码计算：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>line_of_sight = atan2(-Δy, Δx)</span></span></code></pre></div><p>这里的 <code>-Δy</code> 来自该控制律采用的角度符号约定。随后所有角度都经过包外 <code>angles::normalize_angle()</code> 归一化到标准周期范围。</p><h3 id="_3-3-phi-描述目标朝向相对视线的误差" tabindex="-1">3.3 phi 描述目标朝向相对视线的误差 <a class="header-anchor" href="#_3-3-phi-描述目标朝向相对视线的误差" aria-label="Permalink to &quot;3.3 phi 描述目标朝向相对视线的误差&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>phi = normalize(target_yaw + line_of_sight)</span></span></code></pre></div><p><code>phi</code> 不是机器人当前航向误差，而是运动目标期望朝向相对目标视线的关系。它决定慢子系统希望机器人以怎样的姿态收敛到目标 Pose。</p><h3 id="_3-4-delta-描述机器人当前转向相对视线的误差" tabindex="-1">3.4 delta 描述机器人当前转向相对视线的误差 <a class="header-anchor" href="#_3-4-delta-描述机器人当前转向相对视线的误差" aria-label="Permalink to &quot;3.4 delta 描述机器人当前转向相对视线的误差&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>delta = normalize(current_yaw + line_of_sight)</span></span></code></pre></div><p><code>delta</code> 把机器人当前朝向与目标视线联系起来。实时计算默认 <code>current_yaw=0</code>，因为运动目标已经被变换到机器人基坐标系。</p><h3 id="_3-5-倒车会翻转视线和目标朝向" tabindex="-1">3.5 倒车会翻转视线和目标朝向 <a class="header-anchor" href="#_3-5-倒车会翻转视线和目标朝向" aria-label="Permalink to &quot;3.5 倒车会翻转视线和目标朝向&quot;">​</a></h3><p>当 <code>allow_backward=true</code> 且运动目标位于机器人后方，也就是 <code>motion_target.x &lt; 0</code>，主控制器进入 reversing 模式。</p><p>主控制器把运动目标 yaw 加上 π；极坐标构造又把视线翻转到倒车方向。控制律随后反转曲率符号和线速度符号，使机器人以负 <code>linear.x</code> 接近目标，同时保持所需转向关系。</p><p>当前参数逻辑不允许 <code>initial_rotation</code> 和 <code>allow_backward</code> 同时生效。构造阶段两者都为 true 时会关闭倒车；动态修改发生冲突时，包内参数会忽略冲突值。</p><h2 id="四、平滑控制律如何从姿态误差得到曲率" tabindex="-1">四、平滑控制律如何从姿态误差得到曲率 <a class="header-anchor" href="#四、平滑控制律如何从姿态误差得到曲率" aria-label="Permalink to &quot;四、平滑控制律如何从姿态误差得到曲率&quot;">​</a></h2><p><img src="`+c+`" alt="Lyapunov 平滑曲率控制律"></p><h3 id="_4-1-比例项约束快速转向误差" tabindex="-1">4.1 比例项约束快速转向误差 <a class="header-anchor" href="#_4-1-比例项约束快速转向误差" aria-label="Permalink to &quot;4.1 比例项约束快速转向误差&quot;">​</a></h3><p><code>calculateCurvature()</code> 先计算：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>prop_term = k_delta × [delta - atan(-k_phi × phi)]</span></span></code></pre></div><p><code>atan(-k_phi × phi)</code> 是慢子系统给快速转向子系统的虚拟控制目标。<code>delta</code> 与该目标的差值越大，比例项越强。</p><p><code>k_delta</code> 决定快速子系统修正航向的力度。值越大，机器人越积极地把当前转向角拉向虚拟目标，但角速度也更容易触发上限。</p><h3 id="_4-2-反馈项把视线误差带回闭环" tabindex="-1">4.2 反馈项把视线误差带回闭环 <a class="header-anchor" href="#_4-2-反馈项把视线误差带回闭环" aria-label="Permalink to &quot;4.2 反馈项把视线误差带回闭环&quot;">​</a></h3><p>源码的反馈项为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>feedback_term =</span></span>
<span class="line"><span>  [1 + k_phi / (1 + (k_phi × phi)²)] × sin(delta)</span></span></code></pre></div><p>它同时依赖 <code>phi</code> 和 <code>delta</code>。当 <code>phi</code> 接近零时，分式中的增益更明显；当目标姿态误差增大时，分母抑制该附加增益，避免修正无限放大。</p><h3 id="_4-3-曲率把两个子系统合并" tabindex="-1">4.3 曲率把两个子系统合并 <a class="header-anchor" href="#_4-3-曲率把两个子系统合并" aria-label="Permalink to &quot;4.3 曲率把两个子系统合并&quot;">​</a></h3><p>最终曲率为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kappa = -(prop_term + feedback_term) / r</span></span></code></pre></div><p>曲率绝对值越大，轨迹转弯越急；正负号决定转向方向。<code>k_phi=0</code> 时，目标姿态对慢子系统的影响被大幅削弱，控制器更接近只追位置的 waypoint follower。</p><h3 id="_4-4-r-同时带来收敛能力和奇异风险" tabindex="-1">4.4 r 同时带来收敛能力和奇异风险 <a class="header-anchor" href="#_4-4-r-同时带来收敛能力和奇异风险" aria-label="Permalink to &quot;4.4 r 同时带来收敛能力和奇异风险&quot;">​</a></h3><p>曲率包含 <code>1 / r</code>。机器人接近运动目标时，微小角度误差可能产生很大的曲率。</p><p>源码没有在 <code>calculateCurvature()</code> 内给 <code>r</code> 设置下限，而是依靠运动目标前视距离、目标附近线速度下降、角速度限幅和最终旋转分支共同减轻奇异性。若直接用几乎重合的 Pose 调用控制律，仍需要调用者理解这条边界。</p><h2 id="五、曲率不是速度-控制器还要经过四层约束" tabindex="-1">五、曲率不是速度，控制器还要经过四层约束 <a class="header-anchor" href="#五、曲率不是速度-控制器还要经过四层约束" aria-label="Permalink to &quot;五、曲率不是速度，控制器还要经过四层约束&quot;">​</a></h2><h3 id="_5-1-曲率越大-基础线速度越低" tabindex="-1">5.1 曲率越大，基础线速度越低 <a class="header-anchor" href="#_5-1-曲率越大-基础线速度越低" aria-label="Permalink to &quot;5.1 曲率越大，基础线速度越低&quot;">​</a></h3><p>源码先按曲率生成线速度候选：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v_curve = v_linear_max /</span></span>
<span class="line"><span>          [1 + beta × abs(kappa)^lambda]</span></span></code></pre></div><p><code>beta</code> 控制弯道降速的强度。<code>lambda</code> 控制曲率影响的非线性形状；值越大，高曲率区的速度下降越集中。</p><h3 id="_5-2-距运动目标越近-目标减速越明显" tabindex="-1">5.2 距运动目标越近，目标减速越明显 <a class="header-anchor" href="#_5-2-距运动目标越近-目标减速越明显" aria-label="Permalink to &quot;5.2 距运动目标越近，目标减速越明显&quot;">​</a></h3><p>另一条速度候选为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v_slow = v_linear_max × r / slowdown_radius</span></span>
<span class="line"><span>v      = min(v_curve, v_slow)</span></span></code></pre></div><p>这条规则围绕每个运动目标生效，并不只围绕全局终点生效。由于运动目标通常在路径前方滚动，正常跟踪时 <code>r</code> 会维持在前视距离附近；路径尾端无法再提供足够远的目标后，<code>r</code> 才持续缩小。</p><h3 id="_5-3-最小线速度会重新抬高速度" tabindex="-1">5.3 最小线速度会重新抬高速度 <a class="header-anchor" href="#_5-3-最小线速度会重新抬高速度" aria-label="Permalink to &quot;5.3 最小线速度会重新抬高速度&quot;">​</a></h3><p>随后源码执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v = clamp(v, v_linear_min, v_linear_max)</span></span></code></pre></div><p>这意味着 <code>v_slow</code> 即使接近零，也会被 <code>v_linear_min</code> 抬高。控制律自身不会连续减速到完全静止，最终停车依赖 GoalChecker、最终旋转状态和 Controller Server 的任务终态。</p><p>倒车模式在 clamp 之后把 <code>v</code> 变成负值。</p><h3 id="_5-4-角速度限幅后重新投影线速度" tabindex="-1">5.4 角速度限幅后重新投影线速度 <a class="header-anchor" href="#_5-4-角速度限幅后重新投影线速度" aria-label="Permalink to &quot;5.4 角速度限幅后重新投影线速度&quot;">​</a></h3><p>控制律先计算：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>omega_raw = kappa × v</span></span>
<span class="line"><span>omega     = clamp(omega_raw, -v_angular_max, v_angular_max)</span></span></code></pre></div><p>若角速度触顶，源码不是只截断 <code>omega</code>，而是重新计算：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v = omega / kappa</span></span></code></pre></div><p>这样仍保持 <code>omega / v = kappa</code>，机器人不会因为角速度限幅而改变原计划曲率。代价是最终线速度可能低于前面设置的 <code>v_linear_min</code>；所以 <code>v_linear_min</code> 是角速度限幅之前的下限，不是最终输出的绝对保证。</p><h3 id="_5-5-当前工程参数代表怎样的行为" tabindex="-1">5.5 当前工程参数代表怎样的行为 <a class="header-anchor" href="#_5-5-当前工程参数代表怎样的行为" aria-label="Permalink to &quot;5.5 当前工程参数代表怎样的行为&quot;">​</a></h3><p><code>nav2_regulated_modules</code> 当前配置使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>motion_target_dist = 0.6 m</span></span>
<span class="line"><span>k_phi              = 3.0</span></span>
<span class="line"><span>k_delta            = 2.0</span></span>
<span class="line"><span>beta               = 0.2</span></span>
<span class="line"><span>lambda             = 2.0</span></span>
<span class="line"><span>v_linear_min       = 0.03 m/s</span></span>
<span class="line"><span>v_linear_max       = 0.22 m/s</span></span>
<span class="line"><span>v_angular_max      = 1.0 rad/s</span></span>
<span class="line"><span>slowdown_radius    = 1.5 m</span></span></code></pre></div><p>它把线速度压在实车较保守的范围内，同时保留较大的角速度余量。弯道中一旦 <code>omega</code> 接近上限，线速度会进一步被重新投影降低。</p><h2 id="六、同一个控制周期可能进入三种运动模式" tabindex="-1">六、同一个控制周期可能进入三种运动模式 <a class="header-anchor" href="#六、同一个控制周期可能进入三种运动模式" aria-label="Permalink to &quot;六、同一个控制周期可能进入三种运动模式&quot;">​</a></h2><p><img src="`+r+`" alt="最终旋转、初始旋转、平滑跟踪与倒车分支"></p><h3 id="_6-1-最终旋转优先级最高" tabindex="-1">6.1 最终旋转优先级最高 <a class="header-anchor" href="#_6-1-最终旋转优先级最高" aria-label="Permalink to &quot;6.1 最终旋转优先级最高&quot;">​</a></h3><p>当 <code>final_rotation=true</code>，并且剩余路径累计距离小于 GoalChecker 的位置容差，或 <code>goal_reached_</code> 已经置位，控制器进入最终旋转。</p><p>它读取变换后路径最后一个 Pose 的 yaw，调用 <code>rotateToTarget()</code> 输出零线速度和角速度。<code>goal_reached_</code> 是锁存状态，只有收到新路径时才由 <code>setPlan()</code> 清零，因此进入最终旋转后不会重新退回路径跟踪。</p><h3 id="_6-2-初始旋转处理前方偏角过大" tabindex="-1">6.2 初始旋转处理前方偏角过大 <a class="header-anchor" href="#_6-2-初始旋转处理前方偏角过大" aria-label="Permalink to &quot;6.2 初始旋转处理前方偏角过大&quot;">​</a></h3><p>未进入最终旋转时，如果 <code>initial_rotation=true</code> 且运动目标方位角满足：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>abs(atan2(target.y, target.x)) &gt; initial_rotation_min_angle</span></span></code></pre></div><p>控制器先原地朝向运动目标，避免平滑控制律从大偏角状态生成宽大的扫掠弧线。</p><h3 id="_6-3-常规跟踪直接调用平滑控制律" tabindex="-1">6.3 常规跟踪直接调用平滑控制律 <a class="header-anchor" href="#_6-3-常规跟踪直接调用平滑控制律" aria-label="Permalink to &quot;6.3 常规跟踪直接调用平滑控制律&quot;">​</a></h3><p>两个旋转条件都不成立时，<code>calculateRegularVelocity()</code> 使用运动目标 Pose 计算唯一一组 <code>v</code> 与 <code>omega</code>。</p><p>传入 <code>computeVelocityCommands()</code> 的当前速度没有参与计算，因此该控制器本身不限制加速度和 jerk。项目中的 Velocity Smoother 或底盘控制器仍需承担速度时序平滑。</p><h3 id="_6-4-倒车是常规跟踪的方向变体" tabindex="-1">6.4 倒车是常规跟踪的方向变体 <a class="header-anchor" href="#_6-4-倒车是常规跟踪的方向变体" aria-label="Permalink to &quot;6.4 倒车是常规跟踪的方向变体&quot;">​</a></h3><p>倒车不会创建第四套曲率公式。它仍使用同一个 <code>calculateRegularVelocity()</code>，只是改变目标朝向、极坐标视线、曲率符号和线速度符号。</p><h3 id="_6-5-rotatetotarget-是比例旋转而非严格限幅" tabindex="-1">6.5 rotateToTarget() 是比例旋转而非严格限幅 <a class="header-anchor" href="#_6-5-rotatetotarget-是比例旋转而非严格限幅" aria-label="Permalink to &quot;6.5 rotateToTarget() 是比例旋转而非严格限幅&quot;">​</a></h3><p>源码计算：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>linear.x  = 0</span></span>
<span class="line"><span>angular.z = rotation_scaling_factor</span></span>
<span class="line"><span>            × angle_to_target</span></span>
<span class="line"><span>            × v_angular_max</span></span></code></pre></div><p>这个结果没有再 clamp。若 <code>rotation_scaling_factor × abs(angle_to_target) &gt; 1</code>，输出角速度可能超过 <code>v_angular_max</code>。默认缩放系数为 <code>0.5</code>，最大角误差接近 π 时理论输出约为 <code>1.57 × v_angular_max</code>。</p><h2 id="七、唯一速度指令还要通过前向碰撞预测" tabindex="-1">七、唯一速度指令还要通过前向碰撞预测 <a class="header-anchor" href="#七、唯一速度指令还要通过前向碰撞预测" aria-label="Permalink to &quot;七、唯一速度指令还要通过前向碰撞预测&quot;">​</a></h2><p><img src="`+p+`" alt="单轨迹前向积分与 Costmap 碰撞检查"></p><h3 id="_7-1-当前真实位姿先检查一次" tabindex="-1">7.1 当前真实位姿先检查一次 <a class="header-anchor" href="#_7-1-当前真实位姿先检查一次" aria-label="Permalink to &quot;7.1 当前真实位姿先检查一次&quot;">​</a></h3><p><code>simulateTrajectory()</code> 先把 <code>computeVelocityCommands()</code> 收到的机器人位姿交给 <code>inCollision()</code>。当前 Footprint 已在致命障碍物中时，函数立即返回 false。</p><h3 id="_7-2-积分步长由-costmap-分辨率和最大线速度决定" tabindex="-1">7.2 积分步长由 Costmap 分辨率和最大线速度决定 <a class="header-anchor" href="#_7-2-积分步长由-costmap-分辨率和最大线速度决定" aria-label="Permalink to &quot;7.2 积分步长由 Costmap 分辨率和最大线速度决定&quot;">​</a></h3><p>源码使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dt = costmap_resolution / v_linear_max</span></span></code></pre></div><p>在直线且速度接近最大值时，每次积分大约移动一个栅格。最大迭代数为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>max_iter = 2 × target_distance / costmap_resolution</span></span></code></pre></div><p>系数 2 给弯曲轨迹留出比直线距离更多的积分步数，同时限制异常情况下的无限循环。</p><h3 id="_7-3-calculatenextpose-使用一阶欧拉积分" tabindex="-1">7.3 calculateNextPose() 使用一阶欧拉积分 <a class="header-anchor" href="#_7-3-calculatenextpose-使用一阶欧拉积分" aria-label="Permalink to &quot;7.3 calculateNextPose() 使用一阶欧拉积分&quot;">​</a></h3><p>每轮都基于预测 Pose 重新计算控制律：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x_next   = x + v × dt × cos(yaw)</span></span>
<span class="line"><span>y_next   = y + v × dt × sin(yaw)</span></span>
<span class="line"><span>yaw_next = yaw + omega × dt</span></span></code></pre></div><p>因此预测轨迹的曲率会随 <code>r</code>、<code>phi</code> 和 <code>delta</code> 变化，不是一段固定圆弧。</p><h3 id="_7-4-每个预测-pose-都要回到-costmap-全局坐标系" tabindex="-1">7.4 每个预测 Pose 都要回到 Costmap 全局坐标系 <a class="header-anchor" href="#_7-4-每个预测-pose-都要回到-costmap-全局坐标系" aria-label="Permalink to &quot;7.4 每个预测 Pose 都要回到 Costmap 全局坐标系&quot;">​</a></h3><p>预测从机器人基坐标系原点开始。每个 <code>next_pose</code> 经包外 <code>tf2::doTransform()</code> 转到 Costmap 全局坐标系，再由 <code>inCollision()</code> 查询 Footprint 或机器人半径对应的栅格代价。</p><p>遇到 <code>LETHAL_OBSTACLE</code> 时判碰撞。是否把 <code>INSCRIBED_INFLATED_OBSTACLE</code> 和 <code>NO_INFORMATION</code> 视为碰撞，取决于机器人使用 Footprint 还是半径，以及 Layered Costmap 是否跟踪未知空间。</p><h3 id="_7-5-预测结束条件不是全局-goal" tabindex="-1">7.5 预测结束条件不是全局 Goal <a class="header-anchor" href="#_7-5-预测结束条件不是全局-goal" aria-label="Permalink to &quot;7.5 预测结束条件不是全局 Goal&quot;">​</a></h3><p>预测 Pose 距运动目标小于一个 Costmap 分辨率，或轨迹长度达到 <code>max_iter</code>，循环结束并返回 true。</p><p>这只证明当前控制律在有限预测段内没有检测到碰撞，不代表整条全局路径安全。Controller Server 会在下个周期用更新后的机器人位姿和 Costmap 再计算。</p><h2 id="八、速度限制如何改变控制律" tabindex="-1">八、速度限制如何改变控制律 <a class="header-anchor" href="#八、速度限制如何改变控制律" aria-label="Permalink to &quot;八、速度限制如何改变控制律&quot;">​</a></h2><h3 id="_8-1-百分比限制同时缩放线速度与角速度" tabindex="-1">8.1 百分比限制同时缩放线速度与角速度 <a class="header-anchor" href="#_8-1-百分比限制同时缩放线速度与角速度" aria-label="Permalink to &quot;8.1 百分比限制同时缩放线速度与角速度&quot;">​</a></h3><p><code>setSpeedLimit(speed_limit, true)</code> 以初始最大速度为基准：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v_linear_max  = max(v_linear_max_initial × percent / 100,</span></span>
<span class="line"><span>                    v_linear_min)</span></span>
<span class="line"><span>v_angular_max = v_angular_max_initial × percent / 100</span></span></code></pre></div><p>线速度不会低于 <code>v_linear_min</code>，角速度没有同类最小值。</p><h3 id="_8-2-绝对线速度限制按比例缩放角速度" tabindex="-1">8.2 绝对线速度限制按比例缩放角速度 <a class="header-anchor" href="#_8-2-绝对线速度限制按比例缩放角速度" aria-label="Permalink to &quot;8.2 绝对线速度限制按比例缩放角速度&quot;">​</a></h3><p>绝对限制模式把输入解释为 m/s：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v_linear_max  = max(speed_limit, v_linear_min)</span></span>
<span class="line"><span>v_angular_max = v_angular_max_initial</span></span>
<span class="line"><span>                × speed_limit / v_linear_max_initial</span></span></code></pre></div><p>角速度按原始线速度比例缩放，使外部限速不会只压低平移而保留过高转向能力。</p><h3 id="_8-3-取消限速恢复初始最大值" tabindex="-1">8.3 取消限速恢复初始最大值 <a class="header-anchor" href="#_8-3-取消限速恢复初始最大值" aria-label="Permalink to &quot;8.3 取消限速恢复初始最大值&quot;">​</a></h3><p>收到包外 <code>NO_SPEED_LIMIT</code> 标志时，两个最大速度恢复到参数处理器保存的 initial 值。动态修改最大速度参数也会更新 initial 值，所以恢复的是最近一次参数基线，不一定是进程启动时的默认值。</p><h2 id="九、哪些关键调用不在本包内" tabindex="-1">九、哪些关键调用不在本包内 <a class="header-anchor" href="#九、哪些关键调用不在本包内" aria-label="Permalink to &quot;九、哪些关键调用不在本包内&quot;">​</a></h2><h3 id="_9-1-controller-server-提供执行时机" tabindex="-1">9.1 Controller Server 提供执行时机 <a class="header-anchor" href="#_9-1-controller-server-提供执行时机" aria-label="Permalink to &quot;9.1 Controller Server 提供执行时机&quot;">​</a></h3><p><code>nav2_core::Controller</code> 只定义插件接口。包外 Controller Server 负责接收 <code>FollowPath</code> Action、调用 <code>setPlan()</code>、周期调用 <code>computeVelocityCommands()</code>，并把返回速度发布到后续 Topic。</p><p>Graceful Controller 不拥有导航任务状态机，也不决定何时取消 Action。</p><h3 id="_9-2-tf-与-nav-2d-utils-提供坐标变换" tabindex="-1">9.2 TF 与 nav_2d_utils 提供坐标变换 <a class="header-anchor" href="#_9-2-tf-与-nav-2d-utils-提供坐标变换" aria-label="Permalink to &quot;9.2 TF 与 nav_2d_utils 提供坐标变换&quot;">​</a></h3><p>机器人位姿进入全局路径坐标系、局部路径进入机器人基坐标系，以及预测 Pose 进入 Costmap 全局坐标系，都依赖包外 <code>tf2_ros::Buffer</code>、<code>nav_2d_utils::transformPose()</code> 和 <code>tf2::doTransform()</code>。</p><p>本包只决定变换发生在哪个算法阶段，不实现 TF 缓存和插值。</p><h3 id="_9-3-nav2-util-提供路径数学" tabindex="-1">9.3 nav2_util 提供路径数学 <a class="header-anchor" href="#_9-3-nav2-util-提供路径数学" aria-label="Permalink to &quot;9.3 nav2_util 提供路径数学&quot;">​</a></h3><p>最近点上界、最小距离点、路径累计长度、欧氏距离和 yaw 四元数生成来自包外 <code>nav2_util::geometry_utils</code>。</p><h3 id="_9-4-costmap-提供环境碰撞语义" tabindex="-1">9.4 Costmap 提供环境碰撞语义 <a class="header-anchor" href="#_9-4-costmap-提供环境碰撞语义" aria-label="Permalink to &quot;9.4 Costmap 提供环境碰撞语义&quot;">​</a></h3><p><code>Costmap2DROS</code> 提供分辨率、尺寸、坐标系、Footprint、机器人半径和未知空间策略。<code>FootprintCollisionChecker</code> 负责计算指定 Pose 上的点代价或 Footprint 代价。</p><p>本包只把这些代价值归类为可继续或碰撞。</p><h3 id="_9-5-goalchecker-和-velocity-smoother-补齐终点与时序闭环" tabindex="-1">9.5 GoalChecker 和 Velocity Smoother 补齐终点与时序闭环 <a class="header-anchor" href="#_9-5-goalchecker-和-velocity-smoother-补齐终点与时序闭环" aria-label="Permalink to &quot;9.5 GoalChecker 和 Velocity Smoother 补齐终点与时序闭环&quot;">​</a></h3><p>包外 GoalChecker 提供位置容差，并最终判断导航目标是否完成。Graceful Controller 的平滑控制律只处理几何收敛。</p><p>输入的当前速度未参与控制律，所以加减速度、命令频率补齐和基于 Odometry 的速度反馈，需要由包外 Velocity Smoother、底盘控制器或其他下游模块完成。</p><h2 id="十、读源码时不能忽略的六个边界" tabindex="-1">十、读源码时不能忽略的六个边界 <a class="header-anchor" href="#十、读源码时不能忽略的六个边界" aria-label="Permalink to &quot;十、读源码时不能忽略的六个边界&quot;">​</a></h2><h3 id="_10-1-当前速度输入没有进入算法" tabindex="-1">10.1 当前速度输入没有进入算法 <a class="header-anchor" href="#_10-1-当前速度输入没有进入算法" aria-label="Permalink to &quot;10.1 当前速度输入没有进入算法&quot;">​</a></h3><p><code>computeVelocityCommands()</code> 明确忽略 <code>velocity</code>。控制输出可能在相邻周期发生较大变化，不能把“轨迹几何平滑”误解为“速度和加速度时序平滑”。</p><h3 id="_10-2-原地旋转指令与预测轨迹不是同一条运动" tabindex="-1">10.2 原地旋转指令与预测轨迹不是同一条运动 <a class="header-anchor" href="#_10-2-原地旋转指令与预测轨迹不是同一条运动" aria-label="Permalink to &quot;10.2 原地旋转指令与预测轨迹不是同一条运动&quot;">​</a></h3><p>主函数即使选择了 <code>rotateToTarget()</code>，后面的 <code>simulateTrajectory()</code> 仍调用 <code>SmoothControlLaw::calculateNextPose()</code>，模拟的是向运动目标平移的平滑轨迹，不是实际的原地旋转。</p><p>因此旋转模式下的碰撞验证与真实输出指令并不严格一致。</p><h3 id="_10-3-tf-查询失败仍会返回已经算出的速度" tabindex="-1">10.3 TF 查询失败仍会返回已经算出的速度 <a class="header-anchor" href="#_10-3-tf-查询失败仍会返回已经算出的速度" aria-label="Permalink to &quot;10.3 TF 查询失败仍会返回已经算出的速度&quot;">​</a></h3><p>Costmap 全局坐标变换查询失败时，源码记录错误并直接返回 <code>cmd_vel</code>，不会抛异常，也不会把速度清零。这个分支跳过了前向碰撞预测。</p><h3 id="_10-4-预测轨迹超出-costmap-会按无碰撞处理" tabindex="-1">10.4 预测轨迹超出 Costmap 会按无碰撞处理 <a class="header-anchor" href="#_10-4-预测轨迹超出-costmap-会按无碰撞处理" aria-label="Permalink to &quot;10.4 预测轨迹超出 Costmap 会按无碰撞处理&quot;">​</a></h3><p><code>inCollision()</code> 的 <code>worldToMap()</code> 失败意味着 Pose 不在 Costmap 内。源码只输出警告并返回 false，也就是按“没有碰撞”继续，而不是保守停车。</p><h3 id="_10-5-最终切线方向默认路径至少有两个-pose" tabindex="-1">10.5 最终切线方向默认路径至少有两个 Pose <a class="header-anchor" href="#_10-5-最终切线方向默认路径至少有两个-pose" aria-label="Permalink to &quot;10.5 最终切线方向默认路径至少有两个 Pose&quot;">​</a></h3><p>进入目标附近且 <code>final_rotation=true</code> 时，源码直接访问倒数第二个 Pose 来计算末段切线。<code>PathHandler</code> 只保证变换后路径非空，没有在这里保证至少两个 Pose。</p><p>仅含一个 Pose 的路径进入该分支时存在越界风险。</p><h3 id="_10-6-最小速度不是最终绝对下限" tabindex="-1">10.6 最小速度不是最终绝对下限 <a class="header-anchor" href="#_10-6-最小速度不是最终绝对下限" aria-label="Permalink to &quot;10.6 最小速度不是最终绝对下限&quot;">​</a></h3><p>曲率减速和目标减速之后确实执行了 <code>v_linear_min</code> clamp，但角速度触顶后又用 <code>v=omega/kappa</code> 重新投影。因此最终线速度仍可能低于 <code>v_linear_min</code>。</p><h2 id="十一、graceful-的-优雅-到底来自哪里" tabindex="-1">十一、Graceful 的“优雅”到底来自哪里 <a class="header-anchor" href="#十一、graceful-的-优雅-到底来自哪里" aria-label="Permalink to &quot;十一、Graceful 的“优雅”到底来自哪里&quot;">​</a></h2><h3 id="_11-1-它把位置收敛与姿态收敛放进同一曲率" tabindex="-1">11.1 它把位置收敛与姿态收敛放进同一曲率 <a class="header-anchor" href="#_11-1-它把位置收敛与姿态收敛放进同一曲率" aria-label="Permalink to &quot;11.1 它把位置收敛与姿态收敛放进同一曲率&quot;">​</a></h3><p><code>r</code> 决定距离尺度，<code>phi</code> 表示目标姿态相对视线的误差，<code>delta</code> 表示机器人转向相对视线的误差。曲率控制律让慢位置子系统和快转向子系统协同收敛。</p><h3 id="_11-2-它让速度服从曲率-而不是与曲率争抢" tabindex="-1">11.2 它让速度服从曲率，而不是与曲率争抢 <a class="header-anchor" href="#_11-2-它让速度服从曲率-而不是与曲率争抢" aria-label="Permalink to &quot;11.2 它让速度服从曲率，而不是与曲率争抢&quot;">​</a></h3><p>弯道先通过 <code>beta</code> 和 <code>lambda</code> 主动降速；角速度达到上限后，再反推线速度保持原曲率。这种顺序优先保护几何轨迹形状。</p><h3 id="_11-3-它用滚动目标把复杂路径变成连续局部-pose-跟踪" tabindex="-1">11.3 它用滚动目标把复杂路径变成连续局部 Pose 跟踪 <a class="header-anchor" href="#_11-3-它用滚动目标把复杂路径变成连续局部-pose-跟踪" aria-label="Permalink to &quot;11.3 它用滚动目标把复杂路径变成连续局部 Pose 跟踪&quot;">​</a></h3><p>运动目标始终从局部路径前方重新选择。机器人接近旧目标时，新的目标继续沿路径向前滚动，控制律不需要一次理解完整全局路径。</p><h3 id="_11-4-它的适用边界同样清晰" tabindex="-1">11.4 它的适用边界同样清晰 <a class="header-anchor" href="#_11-4-它的适用边界同样清晰" aria-label="Permalink to &quot;11.4 它的适用边界同样清晰&quot;">​</a></h3><p>Graceful Controller 适合希望以连续姿态收敛生成平滑弧线的差速移动机器人。它不是动态窗口搜索器，不会比较多条避障绕行轨迹；当前唯一预测轨迹发生碰撞时，它会抛出异常，把失败处理交给包外导航编排。</p><p>真正可靠的工程使用，需要同时保证局部路径质量、TF 连续、Costmap 覆盖、GoalChecker 语义、下游速度平滑以及旋转模式的安全边界。</p>`,187)])])}const k=e(d,[["render",h]]);export{x as __pageData,k as default};
